paginas.codigo:
@startuml
node "Clúster Kubernetes" {
  node "worker-1" {
    artifact "qatu-web:8f3c" as web
  }
  node "worker-2" {
    artifact "qatu-api:8f3c" as api
  }
}
database "PostgreSQL (gestionado)" as db
cloud "Pasarela de pagos" as pagos
actor Comprador
Comprador --> web : HTTPS
web --> api : HTTP (ClusterIP)
api --> db : TCP 5432
api --> pagos : HTTPS
@enduml
